import { useCallback, useEffect, useRef } from 'react';
export function useEventCallback(fn) {
  const ref = useRef(fn);

  // TODO: Change to useIsomorphicLayoutEffect
  useEffect(() => {
    ref.current = fn;
  });
  return useCallback((...args) => {
    const fun = ref.current;
    fun(...args);
  }, []);
}